  "confidence": 0.94,
  "anomalies": [
    {
      "category": "bridged_nets",
      "components": ["J1", "J2"],
      "pins": ["J1.25", "J1.27", "J2.27"],
      "nets": ["+5V"],
      "observed": "The schematic connects +5V to J1 pin 25 and J2 pin 27. Because both pins are on the same +5V net, those bus contacts are bridged; J1 pin 27 is not shown connected to +5V.",
      "expected": "The specification says +5V is tied to pin 27 of both M-BUS connectors, and that J1 and J2 carry identical pass-through nets.",
      "evidence": [
        {
          "source": "schematic",
          "quote": "J1: +5V PIN25 25 26 PIN26; J2: +5V 27 28 PIN28 (sheet /, page 1)"
        },
        {
          "source": "spec",
          "quote": "The same +5V net is also tied directly to J1/J2 pin 27"
        },
        {
          "source": "spec",
          "quote": "J1 / J2 ... identical nets on both"
        }
      ],
      "impact": "The board routes +5V to the wrong contact on J1 and ties that contact to J2 pin 27. This breaks the intended pass-through mapping and may put +5V on an unintended M5Stack bus contact.",
      "confidence": 0.94
    }
  ],
  "summary": "The M-BUS connectors do not have the specified matching +5V connection: J1 pin 25 is connected instead of pin 27. This also bridges J1 pin 25 and J2 pin 27 on the +5V net."
}

